```java
	@Override
	public void onInitialize() {
		ClientTickEvents.END_CLIENT_TICK.register(client -> {
			Entity targetedEntity = client.targetedEntity;
			if(targetedEntity != null) {
				EntityDimensions dimensions = targetedEntity.getDimensions(targetedEntity.getPose());
				if(targetedEntity instanceof SlimeEntity slime) {
					client.player.sendMessage(Text.of("H: " + dimensions.height + " W: " + dimensions.width + " Size: " + slime.getSize()), true);
				} else {
					client.player.sendMessage(Text.of("H: " + dimensions.height + " W: " + dimensions.width), true);
				}
			}
		});
	}
```

