package ac.grim.grimac.checks.impl.movement;

import ac.grim.grimac.checks.Check;
import ac.grim.grimac.checks.type.VehicleCheck;
import ac.grim.grimac.player.GrimPlayer;
import ac.grim.grimac.utils.anticheat.update.PositionUpdate;
import ac.grim.grimac.utils.anticheat.update.VehiclePositionUpdate;
import com.github.retrooper.packetevents.util.Vector3d;

public class VehiclePredictionRunner extends Check implements VehicleCheck {
    private static final double MAX_COORDINATE = 30_000_000.0;
    private static final double MAX_MOVEMENT_SQUARED = 50.0 * 50.0;

    public VehiclePredictionRunner(GrimPlayer playerData) {
        super(playerData);
    }

    @Override
    public void process(final VehiclePositionUpdate vehicleUpdate) {
        /*
         * CheckManagerListener constructs this as:
         *
         * new VehiclePositionUpdate(clamp, position, ...)
         *
         * Therefore:
         * - from() is the clamped position
         * - to() is the raw packet position
         */
        Vector3d clampedPosition = vehicleUpdate.from();
        Vector3d packetPosition = vehicleUpdate.to();

        if (!isSafePosition(clampedPosition)
                || !isSafePosition(packetPosition)
                || (!vehicleUpdate.isTeleport() && movedTooFar())) {
            rejectMovement();
            return;
        }

        // Vehicle onGround = false always
        // We don't do normal vehicle setbacks because vehicle netcode sucks.
        player.movementCheckRunner.processAndCheckMovementPacket(
                new PositionUpdate(
                        clampedPosition,
                        packetPosition,
                        false,
                        null,
                        null,
                        vehicleUpdate.isTeleport()
                )
        );
    }

    private boolean movedTooFar() {
        if (!isSafePosition(
                player.lastX,
                player.lastY,
                player.lastZ
        ) || !isSafePosition(
                player.x,
                player.y,
                player.z
        )) {
            return true;
        }

        double deltaX = player.x - player.lastX;
        double deltaY = player.y - player.lastY;
        double deltaZ = player.z - player.lastZ;

        return deltaX * deltaX
                + deltaY * deltaY
                + deltaZ * deltaZ
                >= MAX_MOVEMENT_SQUARED;
    }

    private void rejectMovement() {
        // CheckManagerListener has already assigned the new position.
        // Restore the previous position when it is still valid.
        if (isSafePosition(player.lastX, player.lastY, player.lastZ)) {
            player.x = player.lastX;
            player.y = player.lastY;
            player.z = player.lastZ;
        }

        player.getSetbackTeleportUtil()
                .executeNonSimulatingForceResync();
    }

    private static boolean isSafePosition(Vector3d position) {
        return position != null && isSafePosition(
                position.getX(),
                position.getY(),
                position.getZ()
        );
    }

    private static boolean isSafePosition(
            double x,
            double y,
            double z
    ) {
        return Double.isFinite(x)
                && Double.isFinite(y)
                && Double.isFinite(z)
                && Math.abs(x) <= MAX_COORDINATE
                && Math.abs(y) <= MAX_COORDINATE
                && Math.abs(z) <= MAX_COORDINATE;
    }
}

